%% Person Monostatic/Bistatic RCS at 15 GHz at 6m
if strcmp(target_type, 'person')
    if strcmp(sensing_type, 'monostatic')        
        for ii = 1:length(aod_scatter)
            ang = linspace(0,360,361);
            rcs_norm = lognrnd(mu_rcs,sigma_rcs,length(ang),1);
            diff_abs = abs(ang - aod_scatter(ii));
            [~, closest_idx] = min(diff_abs);
            rcs(ii) = rcs_norm(closest_idx);
        end
    elseif strcmp(sensing_type, 'bistatic')
        for ii = 1:length(aod_scatter)
            ang = linspace(0,360,361);
            % sigma_rcs = 0.14;
            % mu_rcs = 1;
            rcs_norm = lognrnd(mu_rcs,sigma_rcs,length(ang),1);
            diff_abs = abs(ang - aod_scatter(ii));
            [~, closest_idx] = min(diff_abs);
            rcs(ii) = rcs_norm(closest_idx);
        end
    end
end


